xql_query:
// ============================================================
// Rule: CTX_PromptSnatcher Malicious Browser Extension Detected
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_PromptSnatcher Malicious Browser Extension Detected.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================

// Title: PromptSnatcher Extension IDs in Browser Extension Directories
// Description: File create, write, or open events under browser extension directories for the two known malicious extension IDs. Catches installation artifacts on disk and active runtime loading on hosts where the extension is already installed. Covers Chrome, Edge, and Firefox extension directory structures on Windows and macOS.
// MITRE: T1176 (Browser Extensions)
// Reference: MalExt Sentry — PromptSnatcher report (2026-06-13)

config case_sensitive = false
| dataset = xdr_data
| filter event_type = FILE
    and event_sub_type in (ENUM.FILE_CREATE_NEW, ENUM.FILE_WRITE, ENUM.FILE_OPEN)
| filter
    // Extension A — Smart Adblocker
    action_file_path contains "iojpcjjdfhlcbgjnpngcmaojmlokmeii"
    // Extension B — Adblock for Browser
    or action_file_path contains "jcbjcocinigpbgfpnhlpagidbmlngnnn"
| fields _time, agent_hostname, agent_os_type, actor_effective_username,
         actor_process_image_name, actor_process_image_path,
         action_file_path, action_file_name, action_file_extension,
         action_file_sha256, action_file_size, event_sub_type
| sort asc _time
